//! 🧪️ Typed root publication preserves exact original pointers through all independent grant denials.
use semio_framework_value::{RetainedPublicationDecision,RetainedPublicationRoot,RetirementDemand,RetainedCloneGrant,RetainedCloneStep,RetainedAllocationEffect,RetainedWorkOutcome,RetainedWorkPoll,ValueError};
#[path="../../../♻️retirement/📦️owner/🧪️work/effect.rs"]
mod effect;
use std::sync::Arc;
use semio_framework_value_testing_allocator as _;
use std::sync::atomic::{AtomicUsize,Ordering};
struct Decision(AtomicUsize);
impl semio_framework_value::FactoryPayloadRetirement for Decision{type CloseState=();fn close_state_birth_bytes(&self)->usize{0}fn close_state_constructor_depth(&self)->usize{0}fn close_state_constructor_copy_bytes(&self)->usize{0}fn prepare_close_state(&self){}fn close_state_preparation_demands(&self,_:&(),_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}fn close_state_preparation_work_demand(&self,_:&(),_:usize)->Result<u64,ValueError>{Ok(0)}fn prepare_close_state_step(&self,_:&mut(),_:usize,_:&mut RetainedAllocationEffect<'_>)->RetainedWorkPoll{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}fn close_state_preparation_is_complete(_:&())->bool{true}fn transfer_payload(_value:Self,_:&mut()){}fn close_state_demands(_:&(),_:usize)->Result<RetirementDemand,ValueError>{Ok(Default::default())}fn close_state_work_demand(_:&(),_:usize)->Result<u64,ValueError>{Ok(0)}fn close_state_step(_:&mut(),_:usize,_:&mut RetainedAllocationEffect<'_>)->semio_framework_value::OriginalRetirementPoll{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(Default::default())),work:0})}fn close_state_terminal_is_empty(_:&())->bool{true}unsafe fn close_state_terminal_native_release_safe()->bool{true}}
impl RetainedPublicationDecision for Decision{fn committed(&self)->bool{self.0.load(Ordering::Acquire)==1}fn pending(&self)->bool{self.0.load(Ordering::Acquire)==0}}
const MAXIMUM:u64=1<<20;
fn funded<T,E>(g:RetainedCloneGrant,maximum:u64,operation:impl FnOnce(&mut RetainedAllocationEffect<'_>)->RetainedWorkPoll<T,E>)->(RetainedWorkOutcome<T,E>,(usize,usize)){let(poll,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||effect::with_effect(g,maximum,&mut None,operation));(effect::settled(poll),heap)}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn deny(mut g:RetainedCloneGrant,axis:&str)->RetainedCloneGrant{match axis{"items"=>g.maximum_items=0,"copy"=>g.maximum_copy_bytes=0,"capacity"=>g.maximum_capacity_bytes=0,"release"=>g.maximum_release_bytes=0,"depth"=>g.maximum_depth=0,_=>panic!()}g}
#[test]
fn original_publication_root_reveals_all_candidates_at_one_decision_and_returns_original_owners(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for decision in law["decisions"].as_array().unwrap(){let gate=Arc::new(Decision(AtomicUsize::new(0)));let mut root=RetainedPublicationRoot::new(vec![3u64,5]);let pointer=root.as_ptr();let mut candidate=Some(vec![7u64,11]);let next_pointer=candidate.as_ref().unwrap().as_ptr();let mut view:Option<Arc<dyn RetainedPublicationDecision>>=Some(gate.clone());let d=RetainedPublicationRoot::<Vec<u64>>::stage_demands();for axis in law["deniedAxes"].as_array().unwrap(){let(p,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||root.stage(&mut candidate,&mut view,deny(grant(d),axis.as_str().unwrap())).unwrap());assert_eq!(p,Default::default());assert_eq!(heap,(0,0));assert_eq!(candidate.as_ref().unwrap().as_ptr(),next_pointer);assert_eq!(root.as_ptr(),pointer);}let(p,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||root.stage(&mut candidate,&mut view,grant(d)).unwrap());assert_eq!(heap,(p.retained_capacity_bytes,0));assert!(candidate.is_none()&&view.is_none());let(mut displaced,mut retirement)=(None,None);assert_eq!(root.settle(&mut displaced,&mut retirement,grant(root.settlement_demands())).unwrap(),Default::default());assert_eq!(root.as_ptr(),pointer);gate.0.store(if decision=="commit"{1}else{2},Ordering::Release);assert_eq!(root.as_slice(),if decision=="commit"{&[7,11]}else{&[3,5]});let d=root.settlement_demands();for axis in law["deniedSettlementAxes"].as_array().unwrap(){let(p,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||root.settle(&mut displaced,&mut retirement,deny(grant(d),axis.as_str().unwrap())).unwrap());assert_eq!(p,Default::default());assert_eq!(heap,(0,0));assert!(displaced.is_none()&&retirement.is_none());}let(p,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||root.settle(&mut displaced,&mut retirement,grant(d)).unwrap());assert_eq!(heap,(0,p.released_bytes));assert_eq!(displaced.as_ref().unwrap().as_ptr(),if decision=="commit"{pointer}else{next_pointer});assert_eq!(root.as_ptr(),if decision=="commit"{next_pointer}else{pointer});let mut retirement=retirement.unwrap();while !retirement.terminal_is_empty(){let d=retirement.demands(4096).unwrap();let(p,heap)={let(t,h)=funded(grant(d),MAXIMUM,|e|retirement.step(4096,e));(t.result.unwrap().progress(),h)};assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));}drop(retirement);drop(root.into_original().ok().unwrap());drop(displaced);drop(gate);}
}

#[test]
fn original_publication_roots_close_both_sources_before_and_after_shared_visibility(){
 use semio_framework_value::retirement::controlled::ControlledRetirement;
 for state in [0,1,2]{let gate=Arc::new(Decision(AtomicUsize::new(0)));let mut first=RetainedPublicationRoot::new(vec![3u64,5]);let mut second=RetainedPublicationRoot::new(vec![13u64,17]);for(root,value)in [(&mut first,7),(&mut second,19)]{let mut candidate=Some(vec![value,value+4]);let mut decision:Option<Arc<dyn RetainedPublicationDecision>>=Some(gate.clone());let d=RetainedPublicationRoot::<Vec<u64>>::stage_demands();root.stage(&mut candidate,&mut decision,grant(d)).unwrap();}assert_eq!(first[0],3);assert_eq!(second[0],13);gate.0.store(state,Ordering::Release);assert_eq!((first[0],second[0]),if state==1{(7,19)}else{(3,13)});for root in [first,second]{let mut close=ControlledRetirement::new(root).ok().unwrap();for turn in 0..10000{if close.terminal_is_empty(){break}let d=close.next_demand(4096).unwrap();for axis in ["items","copy","capacity","release","depth"]{let value=match axis{"items"=>1,"copy"=>d.copy_bytes,"capacity"=>d.capacity_bytes,"release"=>d.release_bytes,_=>d.depth};if value==0{continue}let attempt=deny(grant(d),axis);let(before,heap)=funded(attempt,MAXIMUM,|e|close.step(4096,e));assert_eq!(heap,(0,0));match before.result{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>assert_eq!(error.retained_progress(),Default::default())}}let(p,heap)={let(t,h)=funded(grant(d),MAXIMUM,|e|close.step(4096,e));(t.result.unwrap().progress(),h)};assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(turn<9999);}assert!(close.terminal_is_empty());drop(close);}drop(gate);}
}

#[test]
fn original_publication_root_forwards_actual_close_work_and_caches_zero(){
 use semio_framework_value::retirement::controlled::ControlledRetirement;
 let law:serde_json::Value=serde_json::from_str(include_str!("work.json")).unwrap();
 for state in law["states"].as_array().unwrap(){
  let gate=Arc::new(Decision(AtomicUsize::new(0)));let mut root=RetainedPublicationRoot::new(vec![3u64,5]);let mut candidate=Some(vec![7u64,11]);let mut decision:Option<Arc<dyn RetainedPublicationDecision>>=Some(gate.clone());
  root.stage(&mut candidate,&mut decision,grant(RetainedPublicationRoot::<Vec<u64>>::stage_demands())).unwrap();gate.0.store(state.as_u64().unwrap()as usize,Ordering::Release);
  let mut close=ControlledRetirement::new(root).ok().unwrap();let mut fuel=u128::from(law["fuel"].as_u64().unwrap());let mut capacity=law["byteStock"].as_u64().unwrap()as usize;let mut released=0usize;let mut copied=capacity;
  for turn in 0..law["maxTurns"].as_u64().unwrap(){
   if close.terminal_is_empty(){break}
   let d=close.next_demand(law["body"].as_u64().unwrap()as usize).unwrap();assert!(d.capacity_bytes<=capacity&&d.copy_bytes<=copied&&d.depth<=law["depth"].as_u64().unwrap()as usize);
   for axis in law["deniedAxes"].as_array().unwrap(){let axis=axis.as_str().unwrap();let amount=match axis{"items"=>1,"copy"=>d.copy_bytes,"capacity"=>d.capacity_bytes,"release"=>d.release_bytes,_=>d.depth};if amount==0{continue}
    let (result,heap)=funded(deny(grant(d),axis),MAXIMUM,|e|close.step(law["body"].as_u64().unwrap()as usize,e));assert_eq!(result.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert_eq!(heap,(0,0));match result.result{Ok(step)=>assert_eq!(step.progress(),Default::default()),Err(error)=>assert_eq!(error.retained_progress(),Default::default())}
   }
   let(result,heap)=funded(grant(d),u64::try_from(fuel).unwrap(),|e|close.step(law["body"].as_u64().unwrap()as usize,e));let work=result.work;assert!(work<=fuel);fuel-=work;let p=result.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));assert!(p.retained_capacity_bytes<=capacity&&p.copied_bytes<=copied);capacity-=p.retained_capacity_bytes;copied-=p.copied_bytes;released+=p.released_bytes;assert!(turn+1<law["maxTurns"].as_u64().unwrap());
  }
  assert!(close.terminal_is_empty());assert!(fuel<u128::from(law["fuel"].as_u64().unwrap()));assert!(released>0);let(result,heap)=funded(grant(Default::default()),MAXIMUM,|e|close.step(law["body"].as_u64().unwrap()as usize,e));assert_eq!(result.work,u128::from(law["cachedWork"].as_u64().unwrap()));assert_eq!(result.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));drop(close);drop(gate);
 }
}
